import{_ as a,o as i,c as l,ah as s}from"./chunks/framework.CPHJ30oF.js";const k=JSON.parse('{"title":"16-Docker容器资源隔离-Cgroups-Namespace底层原理深剖","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"1. Namespace：让容器有自己的世界","slug":"_1-namespace-让容器有自己的世界","link":"#_1-namespace-让容器有自己的世界","children":[]},{"level":2,"title":"2. Cgroups：控制容器资源使用","slug":"_2-cgroups-控制容器资源使用","link":"#_2-cgroups-控制容器资源使用","children":[]},{"level":2,"title":"3. Docker 的轻量不是“没有隔离”","slug":"_3-docker-的轻量不是-没有隔离","link":"#_3-docker-的轻量不是-没有隔离","children":[]},{"level":2,"title":"4. 常见 Docker 运行参数与底层对应关系","slug":"_4-常见-docker-运行参数与底层对应关系","link":"#_4-常见-docker-运行参数与底层对应关系","children":[]},{"level":2,"title":"5. 何时需要手动配置资源限制","slug":"_5-何时需要手动配置资源限制","link":"#_5-何时需要手动配置资源限制","children":[]},{"level":2,"title":"6. 常见误区","slug":"_6-常见误区","link":"#_6-常见误区","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/16-Docker容器资源隔离-Cgroups-Namespace底层原理深剖.md","filePath":"docker/16-Docker容器资源隔离-Cgroups-Namespace底层原理深剖.md"}'),r={name:"docker/16-Docker容器资源隔离-Cgroups-Namespace底层原理深剖.md"};function c(o,e,p,d,t,n){return i(),l("div",null,[...e[0]||(e[0]=[s('<h1 id="_16-docker容器资源隔离-cgroups-namespace底层原理深剖" tabindex="-1">16-Docker容器资源隔离-Cgroups-Namespace底层原理深剖 <a class="header-anchor" href="#_16-docker容器资源隔离-cgroups-namespace底层原理深剖" aria-label="Permalink to “16-Docker容器资源隔离-Cgroups-Namespace底层原理深剖”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>Docker 能做到“轻量隔离”，并不是因为它有特殊魔法，而是因为 Linux 内核提供了 Namespace 和 Cgroups。理解这两类机制，才能真正看懂 Docker 为什么既轻量又可控。</p><p>本篇文章从隔离与资源控制两大核心层面，拆解 Docker 的底层原理，并给出常见配置和实践建议。</p><h2 id="_1-namespace-让容器有自己的世界" tabindex="-1">1. Namespace：让容器有自己的世界 <a class="header-anchor" href="#_1-namespace-让容器有自己的世界" aria-label="Permalink to “1. Namespace：让容器有自己的世界”">​</a></h2><p>Namespace 是 Linux 提供的隔离机制，它把进程视图、网络视图、文件系统视图等分离开来。Docker 使用多种 Namespace 组合，构建容器的运行空间。</p><p>常见 Namespace 类型：</p><ul><li>PID Namespace：进程号隔离；</li><li>NET Namespace：网络隔离；</li><li>MNT Namespace：挂载点隔离；</li><li>IPC Namespace：进程间通信隔离；</li><li>UTS Namespace：主机名隔离；</li><li>USER Namespace：用户和组隔离。</li></ul><p>这些 Namespace 共同作用，使容器内看起来像一个独立系统，而不是直接暴露宿主机环境。</p><h2 id="_2-cgroups-控制容器资源使用" tabindex="-1">2. Cgroups：控制容器资源使用 <a class="header-anchor" href="#_2-cgroups-控制容器资源使用" aria-label="Permalink to “2. Cgroups：控制容器资源使用”">​</a></h2><p>Cgroups（Control Groups）提供资源限制和会计能力。它可以限制容器对 CPU、内存、IO、网络等资源的使用，防止单个容器把宿主机拖垮。</p><p>常见 Cgroups 资源类型：</p><ul><li>CPU：<code>--cpus</code>、<code>--cpu-shares</code>；</li><li>内存：<code>--memory</code>、<code>--memory-swap</code>；</li><li>块设备 I/O：<code>--device-read-bps</code>、<code>--device-write-bps</code>；</li><li>PIDs：<code>--pids-limit</code>。</li></ul><p>示例：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cpus=1.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --memory=512m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp:latest</span></span></code></pre></div><p>这条命令让容器最多使用 1 个 CPU 和 512MB 内存。</p><h2 id="_3-docker-的轻量不是-没有隔离" tabindex="-1">3. Docker 的轻量不是“没有隔离” <a class="header-anchor" href="#_3-docker-的轻量不是-没有隔离" aria-label="Permalink to “3. Docker 的轻量不是“没有隔离””">​</a></h2><p>与虚拟机相比，Docker 不虚拟硬件，而是共享内核。它通过 Namespace 实现视图隔离，通过 Cgroups 实现资源控制。这意味着：</p><ul><li>容器启动快；</li><li>资源开销小；</li><li>隔离度低于虚拟机，但通常足够应用级别场景。</li></ul><h2 id="_4-常见-docker-运行参数与底层对应关系" tabindex="-1">4. 常见 Docker 运行参数与底层对应关系 <a class="header-anchor" href="#_4-常见-docker-运行参数与底层对应关系" aria-label="Permalink to “4. 常见 Docker 运行参数与底层对应关系”">​</a></h2><ul><li><code>--network</code>：对应 NET Namespace；</li><li><code>--pid</code>：对应 PID Namespace；</li><li><code>--user</code>：对应 USER Namespace；</li><li><code>--cpus</code>、<code>--memory</code>：对应 Cgroups 资源限制；</li><li><code>--pids-limit</code>：对应 Cgroups PID 限制。</li></ul><h2 id="_5-何时需要手动配置资源限制" tabindex="-1">5. 何时需要手动配置资源限制 <a class="header-anchor" href="#_5-何时需要手动配置资源限制" aria-label="Permalink to “5. 何时需要手动配置资源限制”">​</a></h2><p>当你在单机上运行多个容器，或服务可能出现异常暴涨时，建议显式配置资源限制：</p><ul><li>CPU 和内存限制防止资源争抢；</li><li>PID 限制防止 fork 炸弹；</li><li>I/O 限制防止磁盘占用过高。</li></ul><p>如果不设置，容器会默认享有宿主机大部分资源，可能导致“单个容器拖垮整机”。</p><h2 id="_6-常见误区" tabindex="-1">6. 常见误区 <a class="header-anchor" href="#_6-常见误区" aria-label="Permalink to “6. 常见误区”">​</a></h2><ul><li>误认为 Docker 与宿主机完全隔离。实际上容器共享宿主机内核；</li><li>误以为资源限制越严格越好。过严会导致应用性能问题；</li><li>误以为只需 Namespace 就够。资源控制同样重要。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>Docker 的底层核心就是“Namespace + Cgroups”。Namespace 负责隔离运行视图，Cgroups 负责资源控制。这两者结合，才是 Docker 轻量容器模型的根基。理解它们，能让你更好地设计容器运行策略，而不是盲目把容器当成“轻量虚拟机”。</p>',29)])])}const m=a(r,[["render",c]]);export{k as __pageData,m as default};
